{
  "shot": {
    "composition": "中近景，70mm 焦距，索尼 Venice II 数字摄影机，浅景深，聚焦于人物上半身至大腿区域，背景虚化保留建筑轮廓。",
    "camera_motion": "轻微环绕式平移运动，从右向左缓缓扫过主角身体曲线，在第2.5秒处稍作停顿后微幅俯拍拉回原位，增强画面动态韵律感。"
  },
  "subject": {
    "description": "一位约25岁的东亚女性，拥有乌黑顺滑及腰长发，部分高髻挽起装饰白色小花发簪，面容精致五官立体，皮肤细腻透亮，嘴角含笑露出洁白牙齿；身形丰满圆润却优雅修长，姿态从容自信。",
    "wardrobe": "轻薄透明质感青绿色刺绣汉服套装——内层低胸交领露乳装束缀有细密花卉暗纹，外罩同色系宽袖披风状纱衣饰边勾勒流动线条，腰部系结缎带蝴蝶结收拢腹部曲线，裙摆垂坠如水波荡漾，整体服饰采用丝绸混纺材质具光泽反射效果。"
  },
  "scene": {
    "location": "日式庭院入口旁石径步道前，传统木结构瓦顶屋檐下延伸至绿植围栏之间，左侧可见假山岩石堆叠，右侧设木质门廊通向上台阶楼梯区。",
    "time_of_day": "午后晴朗时段，太阳位于正上方偏东位置投射斜阳光影交错斑驳地面。",
    "environment": "空中漂浮粉色樱花瓣随风轻舞散落四周，远处竹林掩映古朴屏风墙与陶制盆栽点缀其间，空气清新湿润似春末初夏气息弥漫整个空间。"
  },
  "visual_details": {
    "action": "女主角持油纸伞缓步行进同时微笑凝视前方观众视线，步伐稳健节奏舒展呈现古典东方美学意境。",
    "props": [
      "米黄色纸质折叠油纸伞(带有天然竹骨支撑)",
      "三朵固定花朵造型发饰镶嵌额际两侧",
      "灰褐色大理石纹理路砖铺设路径表面光滑反照天光"
    ],
    "action_sequence": [
      "0-1s: 主角双手稳握伞杆站立中央，微微侧首望向镜头笑意盈盈开启迎宾状态",
      "1-2s: 步履轻抬迈出第一步踏上前方碎石板路面带动衣袂拂扬形成涟漪波动特效",
      "2-3s: 抬臂撑开遮阳之傘面朝天空旋转一圈瞬间花瓣飞溅制造诗意浪漫气氛渲染",
      "3-4s: 回眸一笑转身面向远方目光悠然穿梭园林深处留下一抹倩影余晖",
      "4-5s: 缓慢低头闭目静立片刻仿佛融入四季轮回之中呼应画境宁静之美"
    ]
  },
  "cinematography": {
    "lighting": "主光源来自头顶直射强逆光结合辅佐侧面补光强化肌肤肌理层次对比，使衣物褶皱产生微妙金属般折射亮点；阴影过渡柔软温暖而不突兀，模拟真实户外漫射日照条件下的明暗分布规律。",
    "tone": "唯美灵动，典雅神秘，充满诗情画意般的东方仙幻气质，兼具现代数字高清逼真还原技术带来的超凡视觉冲击力"
  }
}
